<?php
if(!defined('APP_ENTRY'))exit;
$role=$user['role'];$teacher=$role==='teacher';$admin=$role==='admin';$uid=(int)$user['id'];
$edit=positive_query('edit');$class=positive_query('class');$detail=positive_query('detail');$term=term_query();$period=query('period')?:'prelim';if(!isset(GRADE_PERIODS[$period]))missing();
if(!$teacher&&$edit)deny();if($role==='staff'&&$detail)deny();
$q=search_term();$context=($class?['class'=>$class]:[])+($term?['term'=>$term]:[])+($q!==''?['q'=>$q]:[]);
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!$teacher&&!$admin)deny();
 try{
  $en=id_field('enrollment_id');$p=period_field();$action=post('action');
  if(($admin&&$action!=='unlock')||($teacher&&!in_array($action,['save','delete','submit'],true)))deny();
  transaction(function()use($uid,$en,$p,$action,$teacher){
   $owner=one('SELECT e.id,c.teacher_id FROM enrollments e JOIN classes c ON c.id=e.class_id WHERE e.id=? FOR UPDATE',[$en]);
   if(!$owner||($teacher&&(int)$owner['teacher_id']!==$uid))deny();
   $old=one('SELECT * FROM grade_periods WHERE enrollment_id=? AND period=? FOR UPDATE',[$en,$p]);
   if($action==='unlock'){
    if(!$old||!$old['locked_at'])throw new DomainException('This grade is not locked.');
    $reason=text_field('reason',100,'Reopening reason');execute('UPDATE grade_periods SET locked_at=NULL,locked_by=NULL WHERE id=?',[$old['id']]);audit('grade unlocked',"enrollment #$en / $p: $reason");return;
   }
   if($old&&$old['locked_at'])throw new DomainException('This grade is submitted and locked. Ask an administrator to reopen it.');
   if($action==='save'){
    $exam=assessment_input($_POST,'exam');$quiz=assessment_input($_POST,'quiz');$values=$_POST;$values['exam_score']=$exam['score'];$values['quiz_score']=$quiz['score'];$s=compute_grade($values);
    execute('INSERT INTO grade_periods(enrollment_id,period,exam_score,quiz_score,project_score,attendance_score,participation_score,score,recorded_by) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE exam_score=VALUES(exam_score),quiz_score=VALUES(quiz_score),project_score=VALUES(project_score),attendance_score=VALUES(attendance_score),participation_score=VALUES(participation_score),score=VALUES(score),recorded_by=VALUES(recorded_by),updated_at=CURRENT_TIMESTAMP',[$en,$p,$s['exam_score'],$s['quiz_score'],$s['project_score'],$s['attendance_score'],$s['participation_score'],$s['score'],$uid]);
    $gp=one('SELECT id FROM grade_periods WHERE enrollment_id=? AND period=?',[$en,$p])['id'];execute('DELETE FROM grade_assessments WHERE grade_period_id=?',[$gp]);foreach(['exam'=>$exam,'quiz'=>$quiz] as $cat=>$group)foreach($group['items'] as $item)execute('INSERT INTO grade_assessments(grade_period_id,category,title,earned,maximum) VALUES(?,?,?,?,?)',[$gp,$cat,$item['title'],$item['earned'],$item['maximum']]);
    audit('period draft saved',"enrollment #$en / $p: ".($old['score']??'none').' -> '.$s['score']);
   }elseif($action==='submit'){
    if(post('confirm')!=='yes')throw new DomainException('Confirm submission before locking.');if(!$old)throw new DomainException('Save a complete grade before submitting.');
    execute('UPDATE grade_periods SET locked_at=NOW(),locked_by=? WHERE id=?',[$uid,$old['id']]);audit('grade submitted',"enrollment #$en / $p: ".$old['score']);
   }elseif($action==='delete'){confirmed();if(!$old)throw new DomainException('Grade not found.');execute('DELETE FROM grade_periods WHERE id=?',[$old['id']]);audit('period grade deleted',"enrollment #$en / $p: ".$old['score']);}else deny();
  });flash(['save'=>'Draft saved. Review it before submission.','submit'=>'Grade submitted and locked.','unlock'=>'Grade reopened. The assigned teacher can now revise it.','delete'=>'Draft deleted.'][$action]);redirect('grades',[($teacher?'edit':'detail')=>$en,'period'=>$p]+$context);
 }catch(DomainException $ex){$error=$ex->getMessage();}catch(PDOException $ex){error_log_file($ex);$error='Unable to update the grade.';}
}
$base="SELECT en.id enrollment_id,s.name,c.id class_id,c.class_name,c.description,c.units,c.term_id,t.academic_year,t.semester,gs.prelim,gs.midterm,gs.finals,gs.period_count,gs.locked_count,gs.overall,gs.legacy_score FROM enrollments en JOIN students s ON s.id=en.student_id JOIN classes c ON c.id=en.class_id JOIN academic_terms t ON t.id=c.term_id JOIN grade_summary gs ON gs.enrollment_id=en.id WHERE 1=1";
$scope='';$scopeParams=[];if($teacher){$scope=' AND c.teacher_id=?';$scopeParams=[$uid];}elseif($role==='student'){$scope=' AND en.student_id=?';$scopeParams=[$user['student_id']];}
$filter='';$params=$scopeParams;if($q!==''){$filter.=' AND (s.name LIKE ? OR c.class_name LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}if($class){$filter.=' AND c.id=?';$params[]=$class;}if($term){$filter.=' AND c.term_id=?';$params[]=$term;}
$data=rows($base.$scope.$filter.' ORDER BY t.academic_year DESC,c.class_name,s.name',$params);
$selectedRow=null;$breakdown=[];$legacy=null;$assessments=[];$target=$edit??$detail;
if($target){$selectedRow=one($base.$scope.' AND en.id=?',[...$scopeParams,$target]);if(!$selectedRow)missing();$breakdown=array_column(rows('SELECT * FROM grade_periods WHERE enrollment_id=?',[$target]),null,'period');$legacy=one('SELECT score,exam_score,quiz_score,project_score,attendance_score,participation_score FROM grades WHERE enrollment_id=?',[$target]);foreach(rows('SELECT p.period,a.category,a.title,a.earned,a.maximum FROM grade_assessments a JOIN grade_periods p ON p.id=a.grade_period_id WHERE p.enrollment_id=? ORDER BY a.id',[$target]) as $a)$assessments[$a['period']][$a['category']][]=$a;}
$unitAverage=null;if($role==='student'&&$term){$unitAverage=one('SELECT ROUND(SUM(CASE WHEN gs.overall IS NOT NULL AND c.units IS NOT NULL THEN gs.overall*c.units END)/NULLIF(SUM(CASE WHEN gs.overall IS NOT NULL AND c.units IS NOT NULL THEN c.units END),0),2) average_score, SUM(CASE WHEN gs.overall IS NOT NULL AND c.units IS NOT NULL THEN c.units ELSE 0 END) counted_units, COUNT(*) total_subjects, SUM(CASE WHEN gs.overall IS NOT NULL AND c.units IS NOT NULL THEN 1 ELSE 0 END) counted_subjects FROM enrollments en JOIN classes c ON c.id=en.class_id JOIN grade_summary gs ON gs.enrollment_id=en.id WHERE en.student_id=? AND c.term_id=?',[$user['student_id'],$term]);}
$classes=$teacher?rows('SELECT c.id,c.class_name,t.academic_year,t.semester FROM classes c JOIN academic_terms t ON t.id=c.term_id WHERE c.teacher_id=? ORDER BY t.academic_year DESC,c.class_name',[$uid]):[];
?>
<?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?>
<?php if($teacher&&$edit&&$selectedRow):$editing=$breakdown[$period]??null;$locked=$editing&&!empty($editing['locked_at']);$posted=$error&&post('action')==='save';?>
<section class="panel grade-workspace teacher-grade-editor">
<div class="grade-page-heading"><div><div class="grade-eyebrow">TEACHER / GRADE EDITOR</div><h2>Individual assessments</h2><p class="grade-meta"><?=e($selectedRow['name'].' · '.$selectedRow['class_name'].' · '.GRADE_PERIODS[$period])?></p><p class="grade-meta"><?=e($selectedRow['description'].' · '.term_label($selectedRow).' · '.unit_label($selectedRow['units']))?></p></div><a class="button secondary grade-back" href="<?=e(url('grades',$context))?>">Back to list</a></div><div class="period-tabs grade-period-nav"><?php foreach(GRADE_PERIODS as $key=>$label):?><a class="grade-period-link <?=$period===$key?'is-active':''?>" <?=$period===$key?'aria-current="page"':''?> href="<?=e(url('grades',['edit'=>$edit,'period'=>$key]+$context))?>"><span><?=e($label)?></span><strong><?=e(grade_display($breakdown[$key]['score']??null))?></strong><small><?=e(period_status($breakdown[$key]??null))?></small></a><?php endforeach;?></div>
<?php if($legacy):?><div class="notice">Previous overall score: <?=e($legacy['score'])?>. Preserved as a legacy record, not copied into any period.</div><?php endif;?>
<?php if($locked):?><div class="notice">Submitted and locked on <?=e($editing['locked_at'])?>. Only an administrator can reopen this grade. <a href="<?=e(url('grades',['detail'=>$edit]+$context))?>">View full breakdown</a></div><?php else:?>
<?php if($editing&&!isset($assessments[$period])):?><div class="notice">This V3 grade has no individual assessment records. Its saved exam average (<?=e($editing['exam_score'])?>) and quiz average (<?=e($editing['quiz_score'])?>) remain unchanged until you enter actual raw marks and save. You may submit the existing grade as-is.</div><?php endif;?>
<form class="grade-editor-form" method="post" action="<?=e(url('grades',['edit'=>$edit,'period'=>$period]+$context))?>" data-grade-calculator data-raw-assessments><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="enrollment_id" value="<?=e($edit)?>"><input type="hidden" name="period" value="<?=e($period)?>">
<?php foreach(['exam','quiz'] as $cat)assessment_editor($cat,assessment_form_rows($cat,$assessments[$period][$cat]??[],(bool)$posted));?>
<div class="grade-other-components">
<?php foreach(GRADE_COMPONENTS as $key=>[$label,$weight]):if(in_array($key,['exam_score','quiz_score'],true))continue;?><label class="grade-component"><span><strong><?=e($label)?></strong><small><?=$weight?>% weight</small></span><input type="number" name="<?=e($key)?>" min="0" max="100" step="0.01" required data-weight="<?=$weight?>" value="<?=val($key,$editing??[])?>" placeholder="0–100"></label><?php endforeach;?>
</div><div class="grade-editor-total"><div><span>Computed <?=e(GRADE_PERIODS[$period])?> grade</span><output data-grade-result aria-live="polite">—</output><small>Saved overall: <?=e(summary_label($selectedRow))?></small></div><button>Save draft</button></div></form>
<?php if($editing):?><div class="grade-lock-panel"><h3>Submit saved grade</h3><p class="muted">Save your changes first. Submission locks the saved scores and individual assessments; unsaved edits are not included.</p><form method="post" action="<?=e(url('grades',['edit'=>$edit,'period'=>$period]+$context))?>" data-submit-grade><?=csrf_field()?><input type="hidden" name="action" value="submit"><input type="hidden" name="enrollment_id" value="<?=e($edit)?>"><input type="hidden" name="period" value="<?=e($period)?>"><label class="check"><input type="checkbox" name="confirm" value="yes" required> I have reviewed the saved grade</label><button>Submit &amp; lock <?=e(GRADE_PERIODS[$period])?></button></form><form class="spaced" method="post" action="<?=e(url('grades',['edit'=>$edit,'period'=>$period]+$context))?>" data-confirm><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="enrollment_id" value="<?=e($edit)?>"><input type="hidden" name="period" value="<?=e($period)?>"><label class="check"><input type="checkbox" name="confirm" value="yes" required> Confirm</label><button class="danger">Delete draft</button></form></div><?php endif;?>
<?php endif;?><p class="muted spaced">Overall = (Prelim + Midterm + Finals) ÷ 3. Drafts remain visible and marked as such. Demo grading policy, not official HCDC weights.</p></section>
<?php elseif($detail&&$selectedRow):
$firstPeriod=isset($breakdown[$period])?$period:(array_key_first($breakdown)??'prelim');
$overallReady=(int)$selectedRow['period_count']===3;
$allLocked=(int)$selectedRow['locked_count']===3;
$legacyOnly=(int)$selectedRow['period_count']===0&&$selectedRow['legacy_score']!==null;
?>
<section class="panel grade-workspace student-grade-detail">
 <div class="grade-page-heading"><div><div class="grade-eyebrow"><?=e($role==='student'?'STUDENT MANAGER / MY GRADES':'STUDENT MANAGER / GRADE RECORD')?></div><h2><?=e($selectedRow['description']?:$selectedRow['class_name'])?></h2><p class="grade-meta"><?=e($selectedRow['class_name'].' · '.unit_label($selectedRow['units']).' · '.term_label($selectedRow))?></p><?php if($role!=='student'):?><p class="grade-meta"><?=e($selectedRow['name'])?></p><?php endif;?></div><a class="button secondary grade-back" href="<?=e(url('grades',$context))?>">Back to grades</a></div>
 <div class="overall-grade-banner <?=$overallReady?'grade-is-complete':''?>"><span>Overall subject grade</span><strong><?=e($overallReady?grade_display($selectedRow['overall']):($legacyOnly?grade_display($selectedRow['legacy_score']):'—'))?></strong><small><?=e($overallReady?($allLocked?'All periods submitted':'Includes draft grades · subject to change'):($legacyOnly?'Historical grade':'Pending · '.$selectedRow['period_count'].' of 3 periods recorded'))?></small></div>
 <?php foreach(GRADE_PERIODS as $p=>$label):$record=$breakdown[$p]??null; $raw=$assessments[$p]??[];?>
 <details class="grade-period-card" <?=$p===$firstPeriod?'open':''?>>
  <summary><span class="grade-period-info"><strong><?=e($label)?></strong><small><?=e(!$record?'Not recorded':(!empty($record['locked_at'])?'Submitted · Locked':'Draft · Subject to change'))?></small></span><span class="grade-period-value"><?=e(grade_display($record['score']??null))?></span><span class="grade-chevron" aria-hidden="true"></span></summary>
  <div class="grade-period-body">
   <?php if(!$record):?><p class="grade-empty">No grade has been recorded for this period yet.</p><?php else:?>
   <h3>Individual assessment scores</h3>
   <table class="grade-breakdown-table"><thead><tr><th scope="col">Assessment</th><th scope="col">Score</th></tr></thead><tbody>
   <?php foreach(['exam'=>'exam_score','quiz'=>'quiz_score'] as $cat=>$key):?>
    <?php foreach($raw[$cat]??[] as $item):?><tr><td><?=e($item['title'])?></td><td><?=e(grade_display($item['earned']).' / '.grade_display($item['maximum']))?></td></tr><?php endforeach;?>
    <tr class="grade-category-total"><td><?=e(GRADE_COMPONENTS[$key][0])?> <small>(<?=GRADE_COMPONENTS[$key][1]?>% weight)</small><?php if(empty($raw[$cat])):?> <small>· Saved category score</small><?php endif;?></td><td><?=e(grade_display($record[$key]))?>%</td></tr>
   <?php endforeach;?>
   <?php foreach(GRADE_COMPONENTS as $key=>[$component,$weight]):if(in_array($key,['exam_score','quiz_score'],true))continue;?><tr><td><?=e($component)?> <small>(<?=$weight?>% weight)</small></td><td><?=e(grade_display($record[$key]))?>%</td></tr><?php endforeach;?>
   </tbody></table>
   <?php if($admin&&!empty($record['locked_at'])):?><form class="grade-unlock-form" method="post" action="<?=e(url('grades',['detail'=>$detail,'period'=>$p]+$context))?>"><?=csrf_field()?><input type="hidden" name="action" value="unlock"><input type="hidden" name="enrollment_id" value="<?=e($detail)?>"><input type="hidden" name="period" value="<?=e($p)?>"><label>Reason for reopening <?=e($label)?><input type="text" name="reason" maxlength="100" required></label><button class="secondary">Reopen <?=e($label)?></button></form><?php endif;?>
   <?php if($teacher):?><a class="button secondary spaced" href="<?=e(url('grades',['edit'=>$detail,'period'=>$p]+$context))?>"><?=!empty($record['locked_at'])?'View locked grade':'Edit '.e($label).' grade'?></a><?php endif;?>
   <?php endif;?>
  </div>
 </details>
 <?php endforeach;?>
 <?php if($legacy):?><details class="grade-legacy"><summary>Previous overall grade (legacy): <?=e($legacy['score'])?></summary><table class="grade-breakdown-table"><tbody><?php foreach(GRADE_COMPONENTS as $key=>[$label,$weight]):?><tr><td><?=e($label)?></td><td><?=e(grade_display($legacy[$key]))?></td></tr><?php endforeach;?></tbody></table></details><?php endif;?>
 <p class="grade-footnote">A dash means not recorded, not zero. Draft grades may still change. Overall is the average of all three recorded periods.</p>
</section>
<?php else:?>
<section class="panel"><div class="toolbar"><h2><?=$role==='student'?'My grades':'Academic grades'?></h2><form method="get" class="search"><input type="hidden" name="page" value="grades"><input name="q" maxlength="100" placeholder="<?=$role==='student'?'Search subject…':'Search student name…'?>" value="<?=e($q)?>"><?php term_select($term);?><?php if($teacher):?><select name="class" aria-label="Filter by class"><option value="">All assigned subjects</option><?php foreach($classes as $c):?><option value="<?=e($c['id'])?>"<?=selected($class,$c['id'])?>><?=e($c['class_name'].' · '.term_label($c))?></option><?php endforeach;?></select><?php endif;?><button>Search</button><a class="button secondary" href="<?=e(url('grades'))?>">Clear</a></form></div>
<?php if($unitAverage):?><div class="stats"><div class="stat"><span>Unit-weighted average (selected term)</span><strong><?=e(grade_display($unitAverage['average_score']))?></strong><small><?=e($unitAverage['counted_subjects']??0)?> / <?=e($unitAverage['total_subjects'])?> subjects · <?=e($unitAverage['counted_units']??0)?> units counted. Includes saved overall grades; incomplete or unknown units excluded. Not an official HCDC GWA.</small></div></div><?php endif;?>
<p class="muted"><?=$role==='staff'?'Read-only grade records. Only assigned teachers can change scores.':'Click a subject or grade to see its assessment breakdown. Overall is pending until all three periods are recorded.'?></p><?php if($role==='student'):?>
<div class="student-grade-list"><?php foreach($data as $r):?><a class="student-grade-link" href="<?=e(url('grades',['detail'=>$r['enrollment_id']]+$context))?>"><span><strong><?=e($r['description']?:$r['class_name'])?></strong><small><?=e($r['class_name'].' · '.unit_label($r['units']).' · '.term_label($r))?></small></span><span class="student-grade-link-score"><strong><?=e(summary_label($r))?></strong><small><?=e($r['period_count']?$r['locked_count'].' / 3 locked':($r['legacy_score']!==null?'Historical':'Not recorded'))?></small></span><span class="grade-chevron" aria-hidden="true"></span></a><?php endforeach;?><?php if(!$data):?><p class="muted">No matching enrollments.</p><?php endif;?></div>
<?php else:?>
<div class="table-wrap"><table><thead><tr><?php if($role!=='student'):?><th>Student</th><?php endif;?><th>Subject</th><th>Term</th><th>Units</th><th>Prelim</th><th>Midterm</th><th>Finals</th><th>Overall</th><th>Submission</th><?php if($teacher):?><th>Actions</th><?php endif;?></tr></thead><tbody><?php foreach($data as $r):$link=url('grades',['detail'=>$r['enrollment_id']]+$context);?><tr><?php if($role!=='student'):?><td><?=e($r['name'])?></td><?php endif;?><td><?php if($role==='staff'):?><?=e($r['class_name'])?><?php else:?><a href="<?=e($link)?>"><?=e($r['class_name'])?></a><?php endif;?></td><td><?=e(term_label($r))?></td><td><?=e(unit_label($r['units']))?></td><?php foreach(GRADE_PERIODS as $p=>$label):?><td><?=e(grade_display($r[$p]))?></td><?php endforeach;?><td><?php if($role==='staff'):?><span class="pill"><?=e(summary_label($r))?></span><?php else:?><a class="pill" href="<?=e($link)?>"><?=e(summary_label($r))?></a><?php endif;?></td><td><span class="pill <?=((int)$r['locked_count']===3?'status-locked':'status-draft')?>"><?=e($r['period_count']?$r['locked_count'].' / 3 locked':($r['legacy_score']!==null?'Legacy':'Not recorded'))?></span></td><?php if($teacher):?><td><a class="button secondary" href="<?=e(url('grades',['edit'=>$r['enrollment_id'],'period'=>'prelim']+$context))?>">Open grade</a></td><?php endif;?></tr><?php endforeach;?><?php if(!$data):?><tr><td colspan="10">No matching enrollments.</td></tr><?php endif;?></tbody></table></div><?php endif;?></section>
<?php endif;?>
